<?php require_once 'includes/functions.php'; $games = getAllGames(); $found = false; foreach($games as $g) { foreach($g as $k => $v) { if(is_string($v) && preg_match('/[^\x00-\x7F\xC0-\xFF\x{2013}-\x{2014}\x{2018}-\x{201D}\x{00A9}\x{00AE}]/u', $v, $matches)) { foreach(array_unique($matches[0]) as $m) { if(mb_strlen($m)>0 && !preg_match('/\p{L}|\p{M}|\p{P}|\p{Z}/u', $m)) { echo 'DB Emoji in ' . $g['name'] . ': ' . $m . PHP_EOL; $found = true; } } } } } if(!$found) echo 'No emojis in DB!'; ?>
